    <div class="succubus-dialogue-box">
        <div class="avatar-wrapper">
            <img id="char-avatar" alt="リリスの表情" data-mood="$1" class="avatar">
        </div>
        <div class="content-wrapper">
            <div class="char-name">リリス</div>
