<script>
    const IMG_BASE_PATH = 'https://testingcf.jsdelivr.net/gh/eumenes12ds/ASTRAEA-JP@v1.5.8/static/images/lilith/';
    const mood = document.getElementById('char-avatar').dataset.mood.trim(); 

    const DEFAULT_IMG_NAME = 'playful.png'; 
    const DEFAULT_IMG_SRC = IMG_BASE_PATH + DEFAULT_IMG_NAME;

    // 世界書の日本語 mood と旧チャットの中国語 mood を同じ画像に対応させる。
    const MOOD_IMAGES = {
            "厳粛": "serious.png",
            "严肃": "serious.png",
            "お茶目": "playful.png",
            "俏皮": "playful.png",
            "嘲笑": "mocking.png",
            "軽蔑": "disdainful.png",
            "嫌弃": "disdainful.png",
            "祝賀": "celebrating.png",
            "庆祝": "celebrating.png",
            "嬉しい": "happy.png",
            "开心": "happy.png",
            "恐怖": "afraid.png",
            "恐惧": "afraid.png",
            "戦慄": "terrified.png",
            "惊恐": "terrified.png",
            "驚き": "surprised.png",
            "惊讶": "surprised.png",
            "指導": "guiding.png",
            "指导": "guiding.png",
            "叱責": "scolding.png",
            "斥责": "scolding.png",
            "無言": "speechless.png",
            "无语": "speechless.png",
            "怒り": "angry.png",
            "气愤": "angry.png",
            "渇望": "longing.png",
            "渴望": "longing.png",
            "狂喜": "ecstatic.png",
            "号泣": "crying.png",
            "痛哭": "crying.png",
            "エッチ": "flirty.png",
            "色色": "flirty.png",
            "誇り": "proud.png",
            "骄傲": "proud.png",
            "励まし": "encouraging.png",
            "鼓励": "encouraging.png",
            "意地悪笑い": "mischievous.png",
            "坏笑": "mischievous.png",
            "興奮": "excited.png",
            "兴奋": "excited.png"
    };

    function parseAndRender() {
        const avatarEl = document.getElementById('char-avatar');
        const imageName = Object.prototype.hasOwnProperty.call(MOOD_IMAGES, mood) ? MOOD_IMAGES[mood] : DEFAULT_IMG_NAME;
        const targetSrc = IMG_BASE_PATH + imageName;
        updateImageSafe(avatarEl, targetSrc);
    }

    function updateImageSafe(imgEl, targetSrc) {
        const tempImg = new Image();
        tempImg.onload = function() { imgEl.src = targetSrc; };
        tempImg.onerror = function() { 
            if (imgEl.src !== DEFAULT_IMG_SRC) imgEl.src = DEFAULT_IMG_SRC; 
        };
        tempImg.src = targetSrc;
    }

    parseAndRender();
</script>
